import { ALL_TOOL_CONTRACTS, saveAgentLabels, saveExperiment, saveExperimentGroup, saveTemplate, } from "bitfab-lib/mcp-contract";
import { readActivePreviewSession } from "./activePreviewSession.js";
import { pushAgentSessionEvent } from "./agentSessionChannel.js";
import { writeAgentRunId } from "./chatSessions/arming.js";
import { errorResult, McpProxy } from "./mcpProxy.js";
import { resolveCodingAgentDisplayName } from "./resolveCodingAgentDisplayName.js";
function hasText(value) {
    return typeof value === "string" && value.trim() !== "";
}
export function createBitfabToolHandlers(platform, getConfig, pluginVersion) {
    const proxy = new McpProxy(platform, pluginVersion);
    function proxyToolCall(toolName, args) {
        const agentRunId = process.env.BITFAB_AGENT_RUN_ID;
        const isNewAnalyzeRepoPlan = toolName === "save_trace_plan" && !args.planId && hasText(agentRunId);
        if (isNewAnalyzeRepoPlan) {
            const agentSessionId = process.env.CLAUDE_CODE_SESSION_ID;
            if (agentSessionId) {
                writeAgentRunId(agentSessionId, agentRunId);
            }
        }
        const nextArgs = isNewAnalyzeRepoPlan
            ? { ...args, source: args.source ?? "analyze_repo", agentRunId }
            : args;
        return proxy.toolCall(getConfig(), toolName, nextArgs);
    }
    async function pushToActivePreview(event) {
        const active = readActivePreviewSession();
        if (!active) {
            return;
        }
        const config = getConfig();
        if (!config.apiKey) {
            return;
        }
        try {
            await pushAgentSessionEvent({
                serviceUrl: active.serviceUrl,
                apiKey: config.apiKey,
                sessionId: active.sessionId,
            }, event);
        }
        catch { }
    }
    async function handleSaveAgentLabels(args) {
        const { testRunId, labels } = args;
        return proxyToolCall("save_agent_labels", {
            testRunId,
            labels: labels.map((l) => l.originalTraceId !== undefined && l.sourceTraceId === undefined
                ? { ...l, sourceTraceId: l.originalTraceId }
                : l),
        });
    }
    async function handleSaveExperiment(args) {
        const { testRunId, name, notes, experimentGroupId } = args;
        if (name === undefined &&
            notes === undefined &&
            experimentGroupId === undefined) {
            return errorResult("Error saving experiment: provide name, notes, and/or experimentGroupId.");
        }
        return proxyToolCall("save_experiment", {
            testRunId,
            name,
            notes,
            experimentGroupId,
        });
    }
    async function handleSaveExperimentGroup(args) {
        const { experimentGroupId, testRunIds, name, notes } = args;
        if (experimentGroupId === undefined && testRunIds === undefined) {
            return errorResult("Error saving experiment group: testRunIds is required when creating an experiment group.");
        }
        if (experimentGroupId !== undefined && testRunIds !== undefined) {
            return errorResult("Error saving experiment group: testRunIds cannot be provided when editing an experiment group; editing does not change membership.");
        }
        if (experimentGroupId !== undefined &&
            name === undefined &&
            notes === undefined) {
            return errorResult("Error saving experiment group: provide name and/or notes when editing an experiment group.");
        }
        return proxyToolCall("save_experiment_group", {
            experimentGroupId,
            testRunIds,
            name,
            notes,
        });
    }
    async function handleSaveTemplate(args) {
        const { spanType, traceFunctionKey, template, name, description } = args;
        await pushToActivePreview({
            type: "editStarted",
            data: {
                spanType,
                traceFunctionKey: traceFunctionKey ?? null,
                agentLabel: resolveCodingAgentDisplayName(),
            },
        });
        try {
            const result = await proxyToolCall("save_template", {
                spanType,
                traceFunctionKey,
                template,
                name,
                description,
            });
            await pushToActivePreview({
                type: "editEnded",
                data: {
                    spanType,
                    traceFunctionKey: traceFunctionKey ?? null,
                    success: true,
                    summary: traceFunctionKey
                        ? `Updated ${spanType} template for ${traceFunctionKey}`
                        : `Updated org-global ${spanType} template`,
                },
            });
            return result;
        }
        catch (err) {
            await pushToActivePreview({
                type: "editEnded",
                data: {
                    spanType,
                    traceFunctionKey: traceFunctionKey ?? null,
                    success: false,
                    summary: err.message ?? "save_template failed",
                },
            });
            throw err;
        }
    }
    const specialHandlers = {
        [saveAgentLabels.name]: handleSaveAgentLabels,
        [saveExperiment.name]: handleSaveExperiment,
        [saveExperimentGroup.name]: handleSaveExperimentGroup,
        [saveTemplate.name]: handleSaveTemplate,
    };
    const handlers = ALL_TOOL_CONTRACTS.map((contract) => ({
        contract,
        handle: specialHandlers[contract.name] ??
            ((args) => proxyToolCall(contract.name, args)),
    }));
    return { proxy, handlers };
}
